    function maximumUnits($boxTypes, $truckSize) {
        if($truckSize <= 0) return 0;

        usort($boxTypes, function($a, $b) {
            return $b[1] <=> $a[1];
        });

        $finalUnits = 0;

        foreach($boxTypes as $set){
            $numberOfBox= $set[0];
            $numberOfUnits= $set[1];
            if($truckSize <= 0) {
                break;
            }
            elseif($truckSize >= $numberOfBox){
                $finalUnits += $numberOfUnits*$numberOfBox;
                $truckSize   -= $numberOfBox;
            }else{
                $finalUnits += $numberOfUnits * $truckSize;
                $truckSize = 0;
            }
        }
        return $finalUnits;
    }   



    function canJump($nums) {
        //forward approach
        $length = count($nums);
        if($nums == 0) return false;

        $maxIndex = 0;
        for($i=0;$i<$length-1;$i++){
            if($i>$maxIndex) return false;
            $maxIndex = max($maxIndex, $i+$nums[$i]);
        }
        return $maxIndex >= $length-1 ? true : false;


        //backward approach
        $goal = $length - 1;
        for($i=$length-1; $i>=0; $i--){
            if($i + $nums[$i] >= $goal){
                $goal = $i;
            }
        }
        return $goal == 0;
    }


    function solve($nums) {
        sort($nums);
        $totalWaitingTimeForIthIndex = 0;
        $totalWaitingTime = 0;
        $n = count($nums);

        for($i = 1; $i < $n; $i++){
            $totalWaitingTimeForIthIndex += $nums[$i-1];
            $totalWaitingTime += $totalWaitingTimeForIthIndex;
        }

        return intdiv($totalWaitingTime, $n);
}

