function leastInterval($tasks, $n) {

    // 1. Count frequency of each task
    $freq = array_fill(0, 26, 0);

    foreach ($tasks as $task) {
        $index = ord($task) - ord('A');
        $freq[$index]++;
    }

    // 2. Keep only tasks that exist
    $heap = array_values(array_filter($freq, fn($f) => $f > 0));

    // 3. Sort highest frequency first
    rsort($heap);

    //print_r($heap);

    // [remaining count, available time]
    $cooldown = [];

    $time = 0;

    // 4. Continue until no task remains
    while (!empty($heap) || !empty($cooldown)) {

        $time++; //echo $time;

        // 5. Move tasks whose cooldown has finished
        if (!empty($cooldown) && $cooldown[0][1] <= $time) {

            [$count, $availableTime] = array_shift($cooldown);
            echo "-->";print_r([$count, $availableTime]); echo "<--";
             

            $heap[] = $count;

            rsort($heap);
        }

        // 6. Execute an available task
        if (!empty($heap)) {

            $count = array_shift($heap);

            $count--;

            // 7. If this task still has copies,
            // put it into cooldown
            if ($count > 0) {

                $cooldown[] = [
                    $count,
                    $time + $n + 1
                ];
            }
        }

        // If heap is empty:
        // CPU stays IDLE for this interval.
        echo $time."--\n--Heap";
        print_r($heap);echo "\n--Cooldown";
        print_r($cooldown); echo "--time\n";
    }

    return $time;
}


